<script setup lang="ts">
/**
 * Verbatim code (`design/components/code-block.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/code-block.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  Text as TextVNode,
  computed,
  isVNode,
  onBeforeUnmount,
  onMounted,
  ref,
  useTemplateRef,
  watch,
} from 'vue'

import { useTrackedSlots } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/code-block.module.css'
import Button from '../controls/Button.vue'

export interface CodeBlockProps {
  /**
   * What a screen reader hears after a copy, default `'Copied'`; apps pass a localized one.
   */
  copiedLabel?: string
  /**
   * Draws the copy control, the block's only control.
   */
  copyable?: boolean
  /**
   * The copy control's accessible name, default `'Copy'`; apps pass a localized one.
   */
  copyLabel?: string
  /**
   * The accessible name when the block overflows and becomes a scroll region; defaults to `'Code
   * block'`, and apps pass a localized one.
   */
  label?: string
}

defineOptions({ name: 'CodeBlock', inheritAttrs: false })

const props = withDefaults(defineProps<CodeBlockProps>(), {
  copiedLabel: 'Copied',
  copyable: false,
  copyLabel: 'Copy',
  label: 'Code block',
})
const callerSlots = defineSlots<{ default: (props: Record<string, never>) => unknown }>()
const slots = useTrackedSlots(callerSlots)
// The text the caller put in a slot: its text nodes, in order, without the elements'.
const slotText = (slot: ((...args: never[]) => unknown) | undefined): string => {
  const read = (nodes: unknown): string =>
    typeof nodes === 'string'
      ? nodes
      : Array.isArray(nodes)
        ? nodes.map(read).join('')
        : isVNode(nodes) && nodes.type === TextVNode
          ? read(nodes.children)
          : ''
  return read(slot?.())
}
const overflowing = ref(false)
const copied = ref(false)
const copies = ref(0)
const block = useTemplateRef<HTMLElement>('block')
const copy = computed(
  () => () =>
    void navigator.clipboard.writeText(slotText(slots.default)).then(
      () => {
        copied.value = true
        copies.value += 1
      },
      () => undefined,
    ),
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    overflowing.value = block.value !== null && block.value.scrollWidth > block.value.clientWidth
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [block.value]) if (element) resize?.observe(element)
  const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
  for (const element of [block.value])
    if (element) mutation?.observe(element, { childList: true, characterData: true, subtree: true })
  release1 = () => {
    resize?.disconnect()
    mutation?.disconnect()
  }
  run()
}
onMounted(effect1)
watch(() => props.copyable, effect1, { flush: 'post' })
onBeforeUnmount(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const timer = setTimeout(() => {
    copied.value = false
  }, 2000)
  release2 = () => clearTimeout(timer)
}
watch(() => copies.value, effect2, { flush: 'post' })
onBeforeUnmount(() => release2?.())
</script>

<template>
  <div v-if="copyable" :class="styles.copyable" :data-state="copied ? 'copied' : undefined">
    <pre
      ref="block"
      :class="styles.block"
      :data-overflowing="overflowing ? '' : undefined"
      :data-copyable="copyable ? '' : undefined"
      :tabindex="overflowing ? 0 : undefined"
      :role="overflowing ? 'region' : undefined"
      :aria-label="overflowing ? label : undefined"
      data-member="code-block"
    >
      <code>
        <slot />
      </code>
    </pre>
    <div :class="styles.control">
      <Button
        variant="ghost"
        tone="neutral"
        size="sm"
        :iconOnly="true"
        :icon="copied ? 'confirm' : 'copy'"
        :label="copyLabel"
        @click="copy()"
      />
    </div>
    <span :class="styles.reader" aria-live="polite">
      {{ copied ? copiedLabel : '' }}
    </span>
  </div>
  <pre
    v-else
    ref="block"
    :class="styles.block"
    :data-overflowing="overflowing ? '' : undefined"
    :data-copyable="copyable ? '' : undefined"
    :tabindex="overflowing ? 0 : undefined"
    :role="overflowing ? 'region' : undefined"
    :aria-label="overflowing ? label : undefined"
    data-member="code-block"
  >
    <code>
      <slot />
    </code>
  </pre>
</template>
